{
    "summary": {
        "title": "Thinking, Fast and Slow",
        "author": "Daniel Kahneman",
        "core_ideas": [
            {
                "idea": "Dual Process Theory",
                "description": "The human mind operates using two systems: System 1 is fast, intuitive, and emotional; System 2 is slower, logical, and more deliberate. Most of our thinking is done by System 1, which can lead to cognitive biases and errors."
            },
            {
                "idea": "Cognitive Biases",
                "description": "People often make systematic errors in judgment due to mental shortcuts (heuristics) used by System 1. Examples include overconfidence, the anchoring effect, and confirmation bias."
            },
            {
                "idea": "Availability Heuristic",
                "description": "People judge the probability of events based on how easily examples come to mind. This can lead to overestimating the likelihood of dramatic or recent events."
            },
            {
                "idea": "Representativeness Heuristic",
                "description": "People assess the probability of an event by how much it resembles a typical case, often ignoring statistical base rates and leading to incorrect judgments."
            },
            {
                "idea": "Loss Aversion",
                "description": "People prefer avoiding losses rather than acquiring equivalent gains. Losses hurt more than gains feel good, influencing decision-making in various contexts."
            },
            {
                "idea": "Prospect Theory",
