{
  "CAP_Theorem_Explained": {
    "Overview": "The CAP theorem, also known as Brewer's theorem, states that in a distributed system, it is impossible to simultaneously guarantee all three of the following: Consistency, Availability, and Partition Tolerance. A system can only ensure at most two of these three properties at any given time.",
    "CAP_Definitions": {
      "Consistency": "Every read receives the most recent write or an error. All nodes in the system see the same data at the same time.",
      "Availability": "Every request receives a response, without guarantee that it contains the most recent write. The system remains operational even during failures.",
      "Partition_Tolerance": "The system continues to operate despite arbitrary message loss or failure (network partitions)."
    },
    "Examples": [
      {
        "System": "Relational Databases (e.g., MySQL with single node)",
        "Tradeoff": "CP System (Consistency + Partition Tolerance)",
        "Explanation": "These systems prioritize consistency and partition tolerance, but may sacrifice availability during network partitions."
      },
      {
        "System": "Distributed Key-Value Stores (e.g., Apache Cassandra)",
        "Tradeoff": "AP System (Availability + Partition Tolerance)",
        "Explanation": "Cassandra prioritizes availability and partition tolerance, but may return stale data during network partitions."
      },
      {
        "System": "Distributed Databases with synchronous replication (e.g., MongoDB with replica sets in synchronous mode)",
        "Tradeoff": "CA System (Consistency + Availability)",
        "Explanation": "These systems can provide consistency and availability, but they are not partition tolerant and will fail if a network partition occurs."
      }
    ]
  }
}
