"using System;
using System.Text.RegularExpressions;
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class EmailValidatorTests
{
    [TestMethod]
    public void TestValidEmails()
    {
        Assert.IsTrue(IsValidEmail(\"test@example.com\"));
        Assert.IsTrue(IsValidEmail(\"user.name@sub.domain.com\"));
        Assert.IsTrue(IsValidEmail(\"user+tag@example.co.uk\"));
        Assert.IsTrue(IsValidEmail(\"user.name@domain.com\")); // With dot in local part
    }

    [TestMethod]
    public void TestInvalidEmails()
    {
        Assert.IsFalse(IsValidEmail(\"plainaddress\")); // Missing @ and domain
        Assert.IsFalse(IsValidEmail(\"@missinglocalpart.com\")); // Missing local part
        Assert.IsFalse(IsValidEmail(\"user@.com\")); // Domain cannot start with a dot
        Assert.IsFalse(IsValidEmail(\"user@domaincom\")); // Missing dot in domain
        Assert.IsFalse(IsValidEmail(\"user@domain..com\")); // Consecutive dots in domain
    }

    private bool IsValidEmail(string email)
    {
        // Reasonable regex for email validation
        string pattern = \"
            ^[a-zA-Z0-9._%+-]+          # Local part (before @)
            @
            [a-zA-Z0-9.-]+              # Domain name
            \\.                         # Dot before TLD
            [a-zA-Z]{2,}$              # TLD (2 or more letters)
        \";
        Regex regex = new Regex(pattern, RegexOptions.IgnorePatternWhitespace);
        return regex.IsMatch(email);
    }
}"

"function mergeTwoLists(l1, l2) {
    // Create a dummy node to act as the starting point of the merged list
    let dummy = new ListNode(0);
    // Tail will be used to build the new list by pointing to the last node
    let tail = dummy;

    // Traverse both lists until one of them is empty
    while (l1 && l2) {
        if (l1.val < l2.val) {
            tail.next = l1;
            l1 = l1.next;
        } else {
            tail.next = l2;
            l2 = l2.next;
        }
        tail = tail.next;
    }

    // Attach the remaining elements of l1 or l2, whichever is not null
    tail.next = l1 ? l1 : l2;

    // The merged list is next to the dummy node
    return dummy.next;
}

// Definition for singly-linked list node
class ListNode {
    constructor(val, next = null) {
        this.val = val;
        this.next = next;
    }
}

