"package main

import (
    \"encoding/json\"
    \"fmt\"
    \"io/ioutil\"
    \"os\"
)

// Function to read a JSON file and print top-level keys
func printTopLevelKeys(filename string) {
    // Read the JSON file
    data, err := ioutil.ReadFile(filename)
    if err != nil {
        fmt.Fprintf(os.Stderr, \"Error reading file: %v\\n\", err)
        return
    }

    // Parse the JSON data
    var obj map[string]interface{}
    if err := json.Unmarshal(data, &obj); err != nil {
        fmt.Fprintf(os.Stderr, \"Error parsing JSON: %v\\n\", err)
        return
    }

    // Print top-level keys
    for key := range obj {
        fmt.Println(key)
    }
}

func main() {
    // Example usage: provide the path to your JSON file
    printTopLevelKeys(\"example.json\")
}"
